package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	out := []byte{}
	if n > 0 {
		start := num()
		end := start
		flush := func() {
			if len(out) > 0 {
				out = append(out, '\n')
			}
			out = strconv.AppendInt(out, start, 10)
			if start != end {
				out = append(out, " to "...)
				out = strconv.AppendInt(out, end, 10)
			}
		}
		for i := int64(1); i < n; i++ {
			v := num()
			if v == end+1 { // extends the current run
				end = v
			} else {
				flush()
				start, end = v, v
			}
		}
		flush()
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
